62	func catalogRequests(t *testing.T, status int) (*httptest.Server, *atomic.Int32) {
63		t.Helper()
64		var n atomic.Int32
65		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
66			if r.URL.Path != "/v2/_catalog" {
