	if len(b.entries) != 2 {
		t.Fatalf("entries = %d, want one per declared proxy", len(b.entries))
	}
	if b.entries[0].key == b.entries[1].key {
		t.Fatalf("both proxies answer to the key %q, so one checkbox covers both", b.entries[0].key)
